chrome.runtime.onInstalled.addListener(()=>{console.log("RSVP Speed Reader installed")});chrome.runtime.onMessage.addListener((t,r,e)=>{switch(t.type){case"OPEN_PDF_READER":chrome.tabs.create({url:chrome.runtime.getURL("src/reader/index.html?mode=pdf")}),e({success:!0});break;case"OPEN_EPUB_READER":chrome.tabs.create({url:chrome.runtime.getURL("src/reader/index.html?mode=epub")}),e({success:!0});break;case"READ_CURRENT_PAGE":return o(e),!0;default:e({success:!1,error:"Unknown message type"})}return!1});async function o(t){try{const[r]=await chrome.tabs.query({active:!0,currentWindow:!0});if(!r.id){t({success:!1,error:"No active tab found"});return}if(r.url?.startsWith("chrome://")||r.url?.startsWith("chrome-extension://")){t({success:!1,error:"Cannot read content from browser pages"});return}try{await chrome.scripting.executeScript({target:{tabId:r.id},files:["src/content/content.ts"]})}catch{}await new Promise(a=>setTimeout(a,100));let e=null,c=3;for(;c>0&&!e;)try{e=await chrome.tabs.sendMessage(r.id,{type:"GET_PAGE_CONTENT"})}catch(a){if(c--,c>0)await new Promise(s=>setTimeout(s,150));else throw a}if(e&&e.content){await chrome.storage.session.set({pageContent:{content:e.content,title:e.title,url:e.url,timestamp:Date.now()}});const a=chrome.runtime.getURL("src/reader/index.html?mode=page&view=split");await chrome.tabs.create({url:a}),t({success:!0})}else t({success:!1,error:"Could not get page content"})}catch(r){console.error("Error reading page:",r),t({success:!1,error:String(r)})}}
